#include <cstdint>
#include <iostream>
#include <vector>

struct AckState
{
    std::uint16_t latest{};
    std::uint32_t bits{};
    bool any{};

    void onReceive(std::uint16_t seq) {}
};

int main()
{
    AckState a{};
    for (std::uint16_t s : {96, 97, 99, 100}) a.onReceive(s);
    std::cout << a.latest << ' ' << a.bits << '\n';
}
